WITH ranked AS (SELECT * FROM accounts QUALIFY ROW_NUMBER() OVER (PARTITION BY status, account_type ORDER BY opened_date DESC NULLS LAST, id) = 1) SELECT customer_id, CASE WHEN balance >= 82000 THEN 'PREMIUM' ELSE 'STANDARD' END AS balance_tier, COUNT(CASE WHEN status = 'OPEN' THEN 1 END) AS open_count, SUM(CASE WHEN status = 'FROZEN' THEN balance ELSE 0 END) AS frozen_balance, STDDEV_SAMP(balance) AS balance_stddev, SIZE(COLLECT_SET(status)) AS num_status FROM ranked GROUP BY 1, 2;
